import java.io.*;

public class Perturbed4 {
    static boolean DEBUG_FLAG = false;

    static long calc(long n, long m) {
        if (n > m) {
            long tmp = n;
            n = m;
            m = tmp;
        }
        long area = n * m;
        if (n <= 3 && m <= 3) {
            if (n == 1 || m == 1) return 0;
            switch ((int) (n * 10 + m)) {
                case 22: return 0;
                case 23: return 4;
                case 33: return 8;
                default: return 0;
            }
        }
        if (n == 1) {
            long rem = m % 6;
            rem = (rem == 4) ? 2 : (rem == 5) ? 1 : rem;
            return area - rem;
        }
        if (n == 2) {
            return (m == 3 || m == 7) ? area - 2 : area;
        }
        return area - area % 2;
    }

    public static void main(String[] args) throws IOException {
        if (args.length > 0 && args[0].equalsIgnoreCase("d")) DEBUG_FLAG = true;
        StreamTokenizer st = new StreamTokenizer(new BufferedReader(new InputStreamReader(System.in)));
        PrintWriter out = new PrintWriter(System.out);

        long start = System.nanoTime();
        st.nextToken();
        int n = (int) st.nval;
        st.nextToken();
        int m = (int) st.nval;
        out.println(calc(n, m));
        long end = System.nanoTime();

        debug("\nTime: " + (end - start) / 1e6 + " \n\n");
        out.close();
    }

    static void debug(String s) {
        if (DEBUG_FLAG) System.out.print(s);
    }
}
